SELECT 900102, 'Inspect the abandoned wagon above camp and recover its log.', 'Mira, Dorn and Teren were inspecting old trail stones. Their abandoned wagon is beside our camp. Search it for the travelers'' log. Leave what supplies remain for the survivors.', 'Speak with Maruut Stonebinder at the expedition camp in the eastern Charred Vale.', '', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900102 AND owner.`chapter`=1)
