SELECT 900212, 'Defeat Butcher with your collared hound, then defeat Gromm''ko with the hound nearby.', 'Use the leash or ask Devoran to prepare your collar and supervised match. Take your hound to station A and command it to attack Gromm''ko''s raptor Butcher. When the raptor falls, Gromm''ko turns on you. Defeat him while your hound is alive and nearby. You may fight beside it.', 'Speak with Instructor Devoran at the Twilight recruiting compound.', 'Butcher and Gromm''ko defeated', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900212 AND owner.`chapter`=2)
