INSERT INTO `quest_template` (`ID`, `LogDescription`, `QuestDescription`, `QuestCompletionLog`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`)
SELECT 900222, 'Deliver Jarod''s introduction to Dezco at the neutral Dustwallow field camp.', 'Jarod writes an introduction to Sunwalker Dezco. Deliver it to Dezco''s neutral field camp beside the Tabetha road in Dustwallow Marsh. Travel on foot or use your usual routes. His expedition can help us follow the buyers. Keep the letter safe until you reach him.', 'Speak with Sunwalker Dezco at the Dawnchaser field camp beside the Tabetha road in Dustwallow.', '', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900222 AND owner.`chapter`=2)
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `QuestDescription`=VALUES(`QuestDescription`), `QuestCompletionLog`=VALUES(`QuestCompletionLog`), `ObjectiveText1`=VALUES(`ObjectiveText1`), `ObjectiveText2`=VALUES(`ObjectiveText2`), `ObjectiveText3`=VALUES(`ObjectiveText3`), `ObjectiveText4`=VALUES(`ObjectiveText4`);
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`)
SELECT 900222, 'Jarod is free? Then you have already done more than this letter can say. Rest a moment. My people have troubles of their own, and the buyers'' trail passes through them.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900222 AND owner.`chapter`=2)
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
INSERT INTO `quest_request_items` (`ID`, `CompletionText`)
SELECT 900222, 'Jarod''s seal is familiar. Have you brought his letter?' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900222 AND owner.`chapter`=2)
ON DUPLICATE KEY UPDATE `CompletionText`=VALUES(`CompletionText`);
