SELECT 900305, 'Collect 12 marsh lotus leaves and help Kang prepare a second treatment.', 'The antidote eased the fever, but Leza is still weak. Collect twelve marsh lotus leaves among the southern marsh paths. Ask Kang to prepare the treatment when you have them, then return the leaves to me. These are camp supplies, not a test of your herbalism.', 'Speak with Sunwalker Dezco at the Dawnchaser field camp.', 'Lotus remedy prepared with Kang', '', '', '' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900305 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `LogDescription`=VALUES(`LogDescription`), `QuestDescription`=VALUES(`QuestDescription`), `QuestCompletionLog`=VALUES(`QuestCompletionLog`), `ObjectiveText1`=VALUES(`ObjectiveText1`), `ObjectiveText2`=VALUES(`ObjectiveText2`), `ObjectiveText3`=VALUES(`ObjectiveText3`), `ObjectiveText4`=VALUES(`ObjectiveText4`);
