SELECT 900305, 'Kang has prepared what he can from these leaves. We have bought time, not certainty.' WHERE EXISTS (SELECT 1 FROM `mod_customnpcs_bs_content` owner WHERE owner.`kind`='quest' AND owner.`entry`=900305 AND owner.`chapter`=3)
ON DUPLICATE KEY UPDATE `RewardText`=VALUES(`RewardText`);
